DROP TABLE IF EXISTS `papota_sphere_node`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `papota_sphere_node` (
  `node_id` int unsigned NOT NULL COMMENT 'identifiant global, toutes classes confondues',
  `class_id` tinyint unsigned NOT NULL,
  `kind` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '0 = noeud (pierre pre-allouee), 1 = slot (vide, runes)',
  `grid_x` float NOT NULL DEFAULT '0',
  `grid_y` float NOT NULL DEFAULT '0',
  `icon` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `default_stone_entry` int unsigned NOT NULL DEFAULT '0' COMMENT 'entree de la pierre pre-allouee, noeuds uniquement',
  `cluster` int unsigned NOT NULL DEFAULT '0' COMMENT 'cluster d appartenance (rendu)',
  `ring` tinyint unsigned NOT NULL DEFAULT '0' COMMENT 'anneau 1-3 (rendu)',
  `branch` tinyint unsigned NOT NULL DEFAULT '0' COMMENT 'branche 1-8 (rendu)',
  `spell_id` int unsigned NOT NULL DEFAULT '0' COMMENT 'sort custom appris (kind 2 uniquement)',
  PRIMARY KEY (`node_id`),
  KEY `idx_class` (`class_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Spherier Papota : emplacements de la grille, une grille par classe';
